SELECT DISTINCT * FROM shop_options so
JOIN platform_order po ON so.shop_id = po.shop_id
WHERE po.shipping_invoice_number = #{invoiceNumber} OR po.purchase_invoice_number = #{invoiceNumber};

SELECT COUNT(shop_id) FROM shop s JOIN client c ON s.owner_id = c.id LEFT JOIN shop_with_options swo ON s.id = swo.shop_id WHERE swo.has_options IN
#{option}
AND c.active = 1 AND s.active = 1
AND c.id = #{clientId}
AND s.id IN
#{shopId}

SELECT *
FROM shop_with_options swo
WHERE swo.has_options IN

    #{option}


    AND swo.is_client_active = 1
    AND swo.is_shop_active = 1


    AND client_id = #{clientId}


    AND shop_id IN

            #{shopId}


ORDER BY internal_code, client_id, erp_code
LIMIT #{offset}, #{limit};
